/*Schedule AHJ Inspection - Substantially Complete*/
with active_step as (
    INSERT INTO flow.project_process_step (project_id, process_step_id, company_process_step_status_type_id, created_by_id,date_created,migrated_created_date)
        (SELECT project.id,
